"""Second batch of 100 starter knowledge-base notes (total corpus 200)."""

# id, title, source, url, condition, triage, paragraph1, paragraph2, paragraph3
_RAW = [
    ("hangover", "Hangover", "NHS - Hangover", "https://www.nhs.uk/conditions/hangover/", "Hangover", "self_care",
     "A hangover follows heavy alcohol use. Headache, thirst, nausea, tiredness, and sensitivity to light are common the next morning.",
     "Water, rest, bland food, and time are the main care. Do not take more alcohol to 'cure' it. Pain relief may help if it is suitable for you.",
     "See a doctor if vomiting will not stop, you cannot keep fluids down, or you have chest pain, confusion, or a very fast heartbeat."),
    ("jet_lag", "Jet Lag", "CDC - Jet Lag", "https://wwwnc.cdc.gov/travel/page/jet-lag", "Jet Lag", "self_care",
     "Jet lag is a sleep-timing problem after flying across several time zones. People feel sleepy by day, wake at night, and may have a dull headache.",
     "Get daylight in the new morning, keep the first day active, and shift sleep toward local time. Short naps can help. Avoid heavy caffeine late in the day.",
     "See a doctor if sleep problems last more than two weeks after travel or you cannot stay safe while driving."),
    ("hiccups", "Hiccups", "MedlinePlus - Hiccups", "https://medlineplus.gov/ency/article/003068.htm", "Hiccups", "self_care",
     "Hiccups are sudden diaphragm spasms that make a 'hic' sound. Most spells last minutes and are harmless. Eating fast, fizzy drinks, or a big meal can start them.",
     "Sip cold water, pause and breathe slowly, or swallow a teaspoon of sugar. Most bouts stop on their own.",
     "See a doctor if hiccups last more than 48 hours, stop you from eating or sleeping, or follow a head or chest injury."),
    ("muscle_cramp", "Muscle Cramp", "Mayo Clinic - Muscle Cramp", "https://www.mayoclinic.org/diseases-conditions/muscle-cramp/symptoms-causes/syc-20350820", "Muscle Cramp", "self_care",
     "A cramp is a sudden tight, painful knot in a muscle, often in the calf or foot at night or after exercise.",
     "Gently stretch and massage the muscle, walk it out, and drink water. Heat can relax a stubborn cramp.",
     "See a doctor if cramps are very frequent, wake you every night, or you have swelling, weakness, or muscle wasting."),
    ("eye_strain", "Eye Strain from Screens", "AOA - Computer Vision Syndrome", "https://www.aoa.org/healthy-eyes/eye-and-vision-conditions/computer-vision-syndrome", "Eye Strain", "self_care",
     "Screen eye strain causes tired, dry, or burning eyes, blurred near vision, and a dull forehead ache after long computer or phone use.",
     "Use the 20-20-20 rule: every 20 minutes look 20 feet away for 20 seconds. Blink more, raise the screen, and use lubricating drops if needed.",
     "See an eye clinician if pain is severe, vision stays blurred, or one eye is very red."),
    ("viral_sore_throat", "Viral Sore Throat", "CDC - Sore Throat", "https://www.cdc.gov/sore-throat/about/index.html", "Viral Sore Throat", "self_care",
     "Most sore throats are viral. The throat feels scratchy, swallowing hurts a little, and a cough or runny nose often comes with it. Fever is usually mild.",
     "Rest, warm drinks, honey for adults and older children, and simple pain relief help. Antibiotics do not treat viruses.",
     "See a doctor for a severe sore throat with high fever and no cough, or if you cannot swallow saliva."),
    ("laryngitis", "Laryngitis (Hoarse Voice)", "NHS - Laryngitis", "https://www.nhs.uk/conditions/laryngitis/", "Laryngitis", "self_care",
     "Laryngitis is swelling of the voice box, often after a cold or shouting. The voice becomes hoarse or drops to a whisper.",
     "Rest the voice, drink fluids, and avoid whispering which strains the cords. Steam can soothe. Most cases settle in one to two weeks.",
     "See a doctor if hoarseness lasts more than three weeks, you cough blood, or breathing feels tight."),
    ("heat_rash", "Heat Rash", "CDC - Heat Rash", "https://www.cdc.gov/niosh/heat-stress/about/heat-rash.html", "Heat Rash", "self_care",
     "Heat rash is a prickly, itchy cluster of small bumps where sweat is trapped, often on the neck, chest, or skin folds in hot weather.",
     "Move to a cooler place, wear loose cotton, and keep the skin dry. Cool compresses ease itch. Avoid thick ointments that block sweat.",
     "See a doctor if the rash becomes painful, pus-filled, or you develop a fever."),
    ("dry_skin", "Dry Skin (Xerosis)", "AAD - Dry Skin", "https://www.aad.org/public/everyday-care/skin-care-secrets/dry/dry-skin-relief", "Dry Skin", "self_care",
     "Dry skin feels tight, rough, and itchy, especially on the legs and arms in cold weather or after hot showers.",
     "Use lukewarm (not hot) water, a gentle cleanser, and a thick moisturiser right after bathing. A humidifier helps in dry rooms.",
     "See a doctor if the skin cracks and bleeds, itches all night, or a red scaly rash spreads."),
    ("blister", "Skin Blister", "NHS - Blisters", "https://www.nhs.uk/conditions/blisters/", "Blister", "self_care",
     "A blister is a fluid bump from friction, a burn, or a pinch. The roof protects the raw skin underneath.",
     "Leave an intact blister closed, cover it with a clean dressing, and reduce rubbing. If it bursts, do not peel the skin; keep it clean.",
     "See a doctor if the blister is very large, from a burn or chemical, looks infected, or you have diabetes and a foot blister."),
    ("bruise", "Bruise (Contusion)", "MedlinePlus - Bruises", "https://medlineplus.gov/ency/article/007213.htm", "Bruise", "self_care",
     "A bruise is blood under the skin after a bump. It looks red or purple, then green and yellow as it heals over one to two weeks.",
     "Rest, ice wrapped in cloth, and raising the area reduce swelling. Pain relief may help if suitable.",
     "See a doctor for bruises with no injury, bruises after starting a blood thinner, or a bruise that keeps growing with severe pain."),
    ("minor_cut", "Minor Cut", "CDC - Wound Care", "https://www.cdc.gov/hygiene/faq/index.html", "Minor Cut", "self_care",
     "A small cut that stops bleeding with pressure and is not deep can usually be cared for at home.",
     "Wash with clean water, press until bleeding stops, apply a plaster, and keep it dry for a day. Watch for redness or pus.",
     "Seek urgent care if bleeding will not stop, the wound is deep or dirty, a tendon may be cut, or tetanus shots are not up to date."),
    ("ingrown_toenail", "Ingrown Toenail", "NHS - Ingrown Toenail", "https://www.nhs.uk/conditions/ingrown-toenail/", "Ingrown Toenail", "self_care",
     "An ingrown toenail grows into the skin beside the nail, usually the big toe. The edge is sore, red, and sometimes weeps.",
     "Soak the foot in warm water, keep it clean, wear roomy shoes, and do not cut a deep V in the nail. Over-the-counter packs can ease pressure.",
     "See a doctor or podiatrist if there is pus, spreading redness, fever, or you have diabetes."),
    ("plantar_wart", "Plantar Wart", "CDC - HPV and Warts", "https://www.cdc.gov/hpv/about/index.html", "Plantar Wart", "self_care",
     "A plantar wart is a rough, grainy lump on the sole caused by a virus. It may have tiny black dots and hurt when you stand.",
     "Salicylic acid pads from a pharmacy, used for weeks, often clear it. Do not share socks. Cushion the area while it heals.",
     "See a doctor if the lump bleeds, grows fast, or you are not sure it is a wart, especially if you have diabetes."),
    ("stye", "Stye (Hordeolum)", "NEI - Facts About Pink Eye", "https://www.nei.nih.gov/learn-about-eye-health/eye-conditions-and-diseases/pink-eye", "Stye", "self_care",
     "A stye is a painful red lump on the eyelid edge from a blocked oil gland. The eye may water.",
     "Warm compresses for 10 minutes, three or four times a day, usually bring it to a head. Do not squeeze. Avoid eye makeup until it settles.",
     "See a doctor if vision drops, the whole eyelid swells, or the lump lasts more than two weeks."),
    ("blocked_ear", "Blocked Ear from Wax", "NIDCD - Earwax", "https://www.nidcd.nih.gov/health/earwax", "Blocked Ear", "self_care",
     "Earwax can block the canal and cause fullness, muffled hearing, or ringing. Cotton buds often push wax deeper.",
     "Pharmacy wax-softening drops for a few days help many people. Do not syringe if you have a hole in the eardrum or ear discharge.",
     "See a clinician if hearing drops suddenly, you have pain, dizziness, or drops do not help."),
    ("intestinal_gas", "Intestinal Gas and Bloating", "NIDDK - Gas in the Digestive Tract", "https://www.niddk.nih.gov/health-information/digestive-diseases/gas-digestive-tract", "Intestinal Gas", "self_care",
     "Gas and bloating after beans, fizzy drinks, or gulping air are common. The belly feels tight and you pass wind more often.",
     "Eat more slowly, skip extra carbonated drinks, and try smaller meals. A short walk after eating can help.",
     "See a doctor for bloating with weight loss, blood in stool, or pain that wakes you at night."),
    ("travel_diarrhea", "Traveler's Diarrhea", "CDC - Travelers' Diarrhea", "https://wwwnc.cdc.gov/travel/page/travelers-diarrhea", "Traveler's Diarrhea", "self_care",
     "Traveler's diarrhea is sudden loose stools, cramps, and urgency after food or water abroad. Fever is usually low.",
     "Oral rehydration, bottled water, and bland food are first steps. Handwashing protects others. Most cases last a few days.",
     "See a doctor for blood in stool, high fever, or diarrhoea lasting more than three days, especially in children or older adults."),
    ("oral_thrush", "Oral Thrush", "CDC - Candidiasis", "https://www.cdc.gov/candidiasis/about/index.html", "Oral Thrush", "self_care",
     "Oral thrush is a yeast coating on the tongue or inner cheeks. White patches may wipe off and leave a sore red surface. It is more common after antibiotics or with dentures.",
     "Rinse the mouth after inhalers, clean dentures, and see a pharmacist about antifungal gel if it is mild.",
     "See a doctor if patches spread, swallowing hurts, or you have a weak immune system."),
    ("tinea_versicolor", "Tinea Versicolor", "CDC - Fungal Diseases", "https://www.cdc.gov/fungal/about/index.html", "Tinea Versicolor", "self_care",
     "Tinea versicolor causes pale or darker patches on the chest and back, often in warm months. The patches may be mildly scaly and do not tan evenly.",
     "Antifungal shampoo or cream from a pharmacy, used as directed, often clears the yeast. Colour can take weeks to even out.",
     "See a doctor if patches spread despite treatment or you are not sure of the cause."),
    ("hepatitis_b", "Hepatitis B", "CDC - Hepatitis B", "https://www.cdc.gov/hepatitis-b/about/index.html", "Hepatitis B", "consult_doctor",
     "Hepatitis B is a viral liver infection spread by blood or sexual contact. Some people have tiredness, jaundice, and dark urine; others have no early symptoms.",
     "A blood test confirms it. There is a vaccine. Chronic infection needs specialist follow-up to protect the liver.",
     "See a doctor after possible exposure or jaundice. Seek urgent care for confusion or vomiting blood."),
    ("hepatitis_c", "Hepatitis C", "CDC - Hepatitis C", "https://www.cdc.gov/hepatitis-c/about/index.html", "Hepatitis C", "consult_doctor",
     "Hepatitis C is a blood-borne virus that can silently scar the liver for years. Tiredness and jaundice may appear late.",
     "A blood test finds it. Modern antiviral tablets can cure most people when a clinician prescribes them.",
     "Ask for a test if you have risk factors. Seek urgent care for swelling of the belly, confusion, or bleeding."),
    ("hiv", "HIV Infection", "CDC - About HIV", "https://www.cdc.gov/hiv/about/index.html", "HIV", "consult_doctor",
     "HIV is a virus that weakens immune defence if untreated. Early infection can look like a flu with rash and swollen glands, then years may pass with few symptoms.",
     "A test is the only way to know. Antiretroviral treatment lets most people live a long life and stops sexual transmission when the virus is undetectable.",
     "Get tested after risk or if you have unexplained infections. This is not diagnosed from symptoms alone."),
    ("chlamydia", "Chlamydia", "CDC - Chlamydia", "https://www.cdc.gov/chlamydia/about/index.html", "Chlamydia", "consult_doctor",
     "Chlamydia is a common sexually transmitted infection. Many people have no symptoms. Others notice discharge, burning urine, or pelvic pain.",
     "A urine or swab test confirms it. Antibiotics prescribed by a clinician clear it. Partners also need treatment.",
     "See a sexual health clinic for testing. Seek care for severe pelvic pain or fever, which can mean a complication."),
    ("gonorrhea", "Gonorrhea", "CDC - Gonorrhea", "https://www.cdc.gov/gonorrhea/about/index.html", "Gonorrhea", "consult_doctor",
     "Gonorrhea can cause discharge, burning urine, or sore throat after oral sex. Many infections have no symptoms and can spread.",
     "A clinician tests and treats with the current recommended antibiotics. Sex should wait until treatment is complete.",
     "Get tested after unprotected sex or symptoms. Seek urgent care for pelvic or testicular pain with fever."),
    ("syphilis", "Syphilis", "CDC - Syphilis", "https://www.cdc.gov/syphilis/about/index.html", "Syphilis", "consult_doctor",
     "Syphilis starts as a painless sore, then may cause a rash on palms or soles, and later can damage the heart or brain if untreated.",
     "A blood test diagnoses it. Penicillin given by a clinician is the usual cure. Follow-up blood tests check that treatment worked.",
     "See a clinic for any unexplained genital sore or palm rash. This cannot be self-treated."),
    ("yeast_infection", "Vaginal Yeast Infection", "CDC - Candidiasis", "https://www.cdc.gov/candidiasis/about/index.html", "Yeast Infection", "consult_doctor",
     "A vaginal yeast infection causes itch, thick white discharge, and soreness, often after antibiotics.",
     "A clinician can confirm it is not another infection. Antifungal cream or a tablet may be advised. Avoid scented soaps.",
     "See a doctor for a first episode, pregnancy, recurrent infections, or pelvic pain and fever."),
    ("bacterial_vaginosis", "Bacterial Vaginosis", "CDC - Bacterial Vaginosis", "https://www.cdc.gov/bacterial-vaginosis/about/index.html", "Bacterial Vaginosis", "consult_doctor",
     "Bacterial vaginosis is an imbalance of vaginal bacteria. Discharge may be thin and grey with a fishy smell, especially after sex.",
     "A clinician can confirm it. Prescribed antibiotic gel or tablets treat it. Douching makes it more likely to return.",
     "See a clinic rather than guessing, because other infections can look similar."),
    ("pelvic_inflammatory_disease", "Pelvic Inflammatory Disease", "CDC - PID", "https://www.cdc.gov/pid/about/index.html", "Pelvic Inflammatory Disease", "consult_doctor",
     "PID is infection of the uterus or tubes, often after an untreated STI. Lower abdominal pain, fever, and unusual discharge can occur.",
     "It needs prompt antibiotics to protect fertility. Sex partners may also need treatment.",
     "See a doctor the same day for pelvic pain with fever. Seek emergency care if pain is sudden and severe or you faint."),
    ("otitis_externa", "Swimmer's Ear (Otitis Externa)", "CDC - Swimmer's Ear", "https://www.cdc.gov/swimmers-ear/about/index.html", "Otitis Externa", "consult_doctor",
     "Swimmer's ear is infection of the outer ear canal. The ear hurts when the pinna is pulled, and it may itch or drain.",
     "Keep the ear dry. A clinician may prescribe ear drops. Do not poke the canal with buds.",
     "See a doctor for ear pain after swimming. Seek care promptly if you have diabetes or the swelling spreads."),
    ("whooping_cough", "Whooping Cough (Pertussis)", "CDC - Pertussis", "https://www.cdc.gov/pertussis/about/index.html", "Whooping Cough", "consult_doctor",
     "Pertussis starts like a cold, then becomes long bursts of coughing that may end in a whoop or vomiting. Infants can stop breathing.",
     "A clinician may test and give antibiotics to reduce spread. Vaccination protects babies and close contacts.",
     "See a doctor for a cough lasting weeks or any cough in a young infant. Seek emergency care if a baby turns blue."),
    ("rsv", "RSV (Respiratory Syncytial Virus)", "CDC - RSV", "https://www.cdc.gov/rsv/about/index.html", "RSV", "consult_doctor",
     "RSV causes a cold in older children and adults, but can cause wheeze and breathing trouble in infants and older adults.",
     "Care is supportive: fluids, nasal saline, and watching breathing. Some high-risk infants may receive prevention medicine.",
     "See a doctor if a baby feeds poorly or breathes fast. Seek emergency care for pauses in breathing or blue lips."),
    ("mumps", "Mumps", "CDC - Mumps", "https://www.cdc.gov/mumps/about/index.html", "Mumps", "consult_doctor",
     "Mumps causes fever and painful swelling of the salivary glands, making the cheeks look puffy. It spreads in saliva.",
     "Rest and fluids help. There is no specific everyday antiviral. MMR vaccine prevents most cases.",
     "Call a doctor before visiting if you suspect mumps. Seek urgent care for severe headache, stiff neck, or swollen testicles with high fever."),
    ("typhoid", "Typhoid Fever", "CDC - Typhoid Fever", "https://www.cdc.gov/typhoid-fever/about/index.html", "Typhoid", "consult_doctor",
     "Typhoid is a bacterial infection from contaminated food or water. It causes stepwise fever, headache, stomach pain, and sometimes a faint rash.",
     "A blood or stool test confirms it. Prescribed antibiotics and fluids are needed. Vaccination helps travellers to risk areas.",
     "See a doctor for fever after travel to a typhoid region. Seek emergency care for confusion or a rigid abdomen."),
    ("chikungunya", "Chikungunya", "CDC - Chikungunya", "https://www.cdc.gov/chikungunya/about/index.html", "Chikungunya", "consult_doctor",
     "Chikungunya is a mosquito-borne virus. Sudden fever and severe joint pain, often in the hands and feet, are typical. A rash may appear.",
     "There is no specific antiviral. Rest, fluids, and clinician-advised pain relief help. Joint pain can linger for months.",
     "See a doctor after fever and joint pain in a mosquito area. Avoid aspirin if dengue has not been ruled out."),
    ("scabies", "Scabies", "CDC - Scabies", "https://www.cdc.gov/scabies/about/index.html", "Scabies", "consult_doctor",
     "Scabies is a mite infestation. Intense itch, worse at night, appears in finger webs, wrists, and waist. Close contacts often itch too.",
     "A clinician prescribes a cream for the whole body and treats household members at the same time. Wash bedding on a hot cycle.",
     "See a doctor rather than sharing leftover cream. Seek care if the skin becomes infected with pus."),
    ("head_lice", "Head Lice", "CDC - Head Lice", "https://www.cdc.gov/lice/about/head-lice.html", "Head Lice", "consult_doctor",
     "Head lice are small insects on the scalp that cause itch. Nits look like tiny white eggs glued to hair near the skin.",
     "A pharmacist or clinician can advise a licensed lotion and wet-combing. Check close contacts. School exclusion rules vary.",
     "See a clinician if treatments fail or the scalp is very sore and crusted."),
    ("ringworm", "Ringworm (Tinea Corporis)", "CDC - Ringworm", "https://www.cdc.gov/ringworm/about/index.html", "Ringworm", "consult_doctor",
     "Ringworm is a fungal rash, not a worm. It forms a ring-shaped, itchy, scaly patch that slowly grows outward.",
     "Antifungal cream from a pharmacy for two to four weeks often works on the body. Keep the area dry. Do not share towels.",
     "See a doctor if the scalp or nails are involved, or the ring does not fade after home cream."),
    ("impetigo", "Impetigo", "CDC - Impetigo", "https://www.cdc.gov/group-a-strep/about/impetigo.html", "Impetigo", "consult_doctor",
     "Impetigo is a contagious bacterial skin infection. Honey-coloured crusts appear around the nose and mouth, more often in children.",
     "A clinician may prescribe antibiotic cream or tablets. Keep nails short and avoid sharing face cloths.",
     "See a doctor for spreading crusts or fever. Stay home until a clinician says it is no longer catching."),
    ("rosacea", "Rosacea", "NIAMS - Rosacea", "https://www.niams.nih.gov/health-topics/rosacea", "Rosacea", "consult_doctor",
     "Rosacea causes facial redness, flushing, visible vessels, and sometimes acne-like bumps, often on the cheeks and nose.",
     "Triggers include heat, alcohol, and spicy food. A dermatologist may prescribe gels or tablets. Gentle skincare helps.",
     "See a doctor for persistent facial redness. Eye irritation with rosacea also needs review."),
    ("cluster_headache", "Cluster Headache", "NINDS - Cluster Headache", "https://www.ninds.nih.gov/health-information/disorders/cluster-headache", "Cluster Headache", "consult_doctor",
     "Cluster headache is a severe one-sided pain around the eye, with a watery eye and a blocked nostril on that side. Attacks come in bouts.",
     "This is not an ordinary tension headache. A clinician can offer oxygen or prescribed attack medicine. Do not drive during an attack.",
     "See a doctor for a first severe one-sided eye pain. Seek emergency care if it is the worst headache of your life with fever or a stiff neck."),
    ("tinnitus", "Tinnitus (Ringing in the Ears)", "NIDCD - Tinnitus", "https://www.nidcd.nih.gov/health/tinnitus", "Tinnitus", "consult_doctor",
     "Tinnitus is hearing a ring, buzz, or hiss that others cannot hear. Noise exposure, wax, and some medicines are common links.",
     "A hearing check helps. Sound therapy, sleep care, and treating wax or ear disease can reduce the burden. There is rarely a single pill cure.",
     "See a doctor for new tinnitus, especially in one ear, with hearing loss or dizziness."),
    ("cataract", "Cataract", "NEI - Cataracts", "https://www.nei.nih.gov/learn-about-eye-health/eye-conditions-and-diseases/cataracts", "Cataract", "consult_doctor",
     "A cataract clouds the lens of the eye. Vision becomes misty, glare at night increases, and colours look faded. It is common with age.",
     "New glasses help for a while. Surgery to replace the lens is the lasting treatment when daily life is affected.",
     "See an eye clinician for gradual cloudy vision. Sudden vision loss is not a typical cataract and needs urgent care."),
    ("macular_degeneration", "Age-Related Macular Degeneration", "NEI - AMD", "https://www.nei.nih.gov/learn-about-eye-health/eye-conditions-and-diseases/age-related-macular-degeneration", "Macular Degeneration", "consult_doctor",
     "AMD affects central vision used for reading and faces. Straight lines may look wavy. Side vision is usually kept.",
     "An eye specialist can diagnose it. Injections or lifestyle advice may slow some types. Smoking raises risk.",
     "See an eye doctor for new distortion on an Amsler grid. Sudden central dark spots need urgent review."),
    ("tmj_disorder", "TMJ Jaw Pain", "NIDCR - TMJ Disorders", "https://www.nidcr.nih.gov/health-info/tmd", "TMJ Disorder", "consult_doctor",
     "TMJ disorders cause pain in the jaw joint, clicking, and trouble opening the mouth wide. Chewing gum and night grinding make it worse.",
     "Soft food, heat, a night guard if advised, and not resting the chin on a hand help many people.",
     "See a dentist or doctor if the jaw locks, pain lasts weeks, or you cannot eat."),
    ("gingivitis", "Gingivitis (Gum Inflammation)", "CDC - Oral Health", "https://www.cdc.gov/oral-health/about/index.html", "Gingivitis", "consult_doctor",
     "Gingivitis makes gums red, swollen, and easy to bleed when you brush. Plaque left on the teeth is the usual cause.",
     "Twice-daily brushing, daily floss, and a dental clean reverse most early gum disease.",
     "See a dentist for bleeding gums that last. Loose teeth or gum abscesses need prompt dental care."),
    ("chronic_kidney_disease", "Chronic Kidney Disease", "NIDDK - Chronic Kidney Disease", "https://www.niddk.nih.gov/health-information/kidney-disease/chronic-kidney-disease-ckd", "Chronic Kidney Disease", "consult_doctor",
     "CKD is a gradual loss of kidney function. Early stages often have no symptoms. Later, people notice swelling, tiredness, and foamy urine.",
     "Blood and urine tests diagnose it. Blood pressure and diabetes control slow damage. Some medicines need dose changes.",
     "See a doctor for swelling, high blood pressure, or if you have diabetes. Seek urgent care for little or no urine."),
    ("fatty_liver", "Fatty Liver Disease", "NIDDK - NAFLD", "https://www.niddk.nih.gov/health-information/liver-disease/nafld-nash", "Fatty Liver", "consult_doctor",
     "Fatty liver is extra fat in liver cells, often linked to weight, diabetes, or alcohol. Most people feel well at first.",
     "Blood tests and scans find it. Weight loss, activity, and alcohol reduction can reverse early disease.",
     "See a doctor for abnormal liver tests. Seek urgent care for jaundice, swelling, or confusion."),
    ("ulcerative_colitis", "Ulcerative Colitis", "NIDDK - Ulcerative Colitis", "https://www.niddk.nih.gov/health-information/digestive-diseases/ulcerative-colitis", "Ulcerative Colitis", "consult_doctor",
     "Ulcerative colitis is inflammation of the colon lining. Bloody diarrhoea, urgency, and cramps come in flares.",
     "A gastroenterologist confirms it with tests and prescribes anti-inflammatory medicine. Flares need prompt review.",
     "See a doctor for bloody stools lasting more than a few days. Seek emergency care for severe pain, high fever, or fainting."),
    ("crohns_disease", "Crohn's Disease", "NIDDK - Crohn's Disease", "https://www.niddk.nih.gov/health-information/digestive-diseases/crohns-disease", "Crohn's Disease", "consult_doctor",
     "Crohn's can inflame any part of the gut. Pain, diarrhoea, weight loss, and tiredness are common. Mouth ulcers or joint pain may occur.",
     "Specialist drugs and diet support keep many people well. Smoking worsens Crohn's.",
     "See a doctor for lasting gut symptoms and weight loss. Seek emergency care for a rigid abdomen or high fever."),
    ("inguinal_hernia", "Inguinal Hernia", "NIDDK - Inguinal Hernia", "https://www.niddk.nih.gov/health-information/digestive-diseases/inguinal-hernia", "Inguinal Hernia", "consult_doctor",
     "An inguinal hernia is a bulge in the groin that may appear when you cough or stand. It can ache after lifting.",
     "A clinician confirms it. Surgery is often advised if the bulge grows or hurts. Do not try to push a painful stuck bulge repeatedly.",
     "See a doctor for a groin bulge. Seek emergency care if the bulge becomes red, very painful, and will not reduce."),
    ("ovarian_cyst", "Ovarian Cyst", "OASH - Ovarian Cysts", "https://womenshealth.gov/a-z-topics/ovarian-cysts", "Ovarian Cyst", "consult_doctor",
     "Many ovarian cysts are fluid sacs that come and go with the cycle. Some cause one-sided pelvic ache or bloating.",
     "Ultrasound checks the type. Simple cysts are often watched. Hormone treatment or surgery is used if they persist.",
     "See a doctor for pelvic pain that lasts. Seek emergency care for sudden severe one-sided pain with fainting."),
    ("uterine_fibroids", "Uterine Fibroids", "OASH - Uterine Fibroids", "https://womenshealth.gov/a-z-topics/uterine-fibroids", "Uterine Fibroids", "consult_doctor",
     "Fibroids are common non-cancer growths in the womb. They can cause heavy periods, pressure, and a sense of fullness.",
     "A clinician may use ultrasound and offer medicine or procedures if bleeding is heavy.",
     "See a doctor for soaking pads hourly or anaemia symptoms. Sudden severe pain needs same-day care."),
    ("menopause", "Menopause", "OASH - Menopause", "https://womenshealth.gov/menopause", "Menopause", "consult_doctor",
     "Menopause is the end of monthly periods, usually around age 45 to 55. Hot flushes, night sweats, sleep change, and vaginal dryness are common.",
     "A clinician can discuss hormone therapy and non-hormone options. Bone and heart health matter after menopause.",
     "See a doctor for bleeding after 12 months without a period, or if flushes disrupt life."),
    ("gestational_diabetes", "Gestational Diabetes", "CDC - Gestational Diabetes", "https://www.cdc.gov/diabetes/about/gestational-diabetes.html", "Gestational Diabetes", "consult_doctor",
     "Gestational diabetes is high blood sugar first found in pregnancy. Many people feel well. A glucose drink test finds it.",
     "Food planning, activity, and sometimes insulin protect parent and baby. Sugar usually falls after birth, but later type 2 risk is higher.",
     "Attend pregnancy screening. Seek urgent care for very high thirst, vomiting, or reduced baby movements."),
    ("mastitis", "Mastitis", "OASH - Breastfeeding", "https://womenshealth.gov/breastfeeding", "Mastitis", "consult_doctor",
     "Mastitis is inflammation of the breast, often while breastfeeding. A wedge of the breast is red, hot, and painful, and you may have fever.",
     "Frequent feeding or expressing, rest, and a clinician-prescribed antibiotic if infection is likely, are used. Do not stop feeding unless advised.",
     "See a doctor for a red painful breast with fever. Seek urgent care if you feel very unwell or a lump with pus forms."),
    ("type1_diabetes", "Type 1 Diabetes", "CDC - Type 1 Diabetes", "https://www.cdc.gov/diabetes/about/about-type-1-diabetes.html", "Type 1 Diabetes", "consult_doctor",
     "Type 1 diabetes happens when the pancreas stops making insulin. Thirst, lots of urine, weight loss, and tiredness can appear over days or weeks.",
     "Lifelong insulin, prescribed and adjusted by a diabetes team, is required. It is not caused by eating sugar.",
     "See a doctor promptly for these symptoms, especially in a child. Seek emergency care for vomiting, deep breathing, or confusion."),
    ("prediabetes", "Prediabetes", "CDC - Prediabetes", "https://www.cdc.gov/diabetes/prevention-type-2/prediabetes-prevent-type-2.html", "Prediabetes", "consult_doctor",
     "Prediabetes means blood sugar is higher than normal but not yet diabetes. There are often no symptoms. A blood test finds it.",
     "Weight loss if needed, walking most days, and a healthier plate can return sugar toward normal.",
     "Ask for a check if you have a family history, extra weight around the waist, or high blood pressure."),
    ("lupus", "Lupus (SLE)", "NIAMS - Lupus", "https://www.niams.nih.gov/health-topics/lupus", "Lupus", "consult_doctor",
     "Lupus is an autoimmune disease. People may have a facial rash in sun, joint pain, extreme tiredness, and mouth ulcers. It can affect kidneys.",
     "A rheumatologist uses blood tests and clinical signs. Sun protection and prescribed medicine reduce flares.",
     "See a doctor for a lasting butterfly rash with joint pain. Seek urgent care for chest pain or little urine with swelling."),
    ("bursitis", "Bursitis", "NIAMS - Bursitis", "https://www.niams.nih.gov/health-topics/bursitis", "Bursitis", "consult_doctor",
     "Bursitis is inflammation of a small fluid cushion near a joint, often the shoulder, elbow, or hip. The area is sore to press and hurts with movement.",
     "Rest from the trigger activity, ice, and suitable pain relief help. A clinician may inject the bursa if it lingers.",
     "See a doctor if a bursa is hot and you have fever, which can mean infection."),
    ("tendonitis", "Tendonitis", "NIAMS - Tendinitis", "https://www.niams.nih.gov/health-topics/tendinitis", "Tendonitis", "consult_doctor",
     "Tendonitis is irritation of a tendon, such as the Achilles or wrist extensors. Pain is worse with the same repeated movement.",
     "Relative rest, ice, and a gradual return to activity help. A clinician or physiotherapist can guide loading.",
     "See a doctor if you heard a snap and cannot push off or lift the arm, which can be a tendon rupture."),
    ("plantar_fasciitis", "Plantar Fasciitis", "NIAMS - Plantar Fasciitis", "https://www.niams.nih.gov/health-topics/plantar-fasciitis", "Plantar Fasciitis", "consult_doctor",
     "Plantar fasciitis is heel pain that is worst with the first steps in the morning. The band under the foot is tight and sore.",
     "Calf stretches, supportive shoes, and not going barefoot on hard floors help most people over weeks.",
     "See a doctor or podiatrist if you cannot walk or pain lasts more than a few months."),
    ("frozen_shoulder", "Frozen Shoulder", "NIAMS - Frozen Shoulder", "https://www.niams.nih.gov/health-topics/frozen-shoulder-adhesive-capsulitis", "Frozen Shoulder", "consult_doctor",
     "Frozen shoulder slowly stiffens the shoulder so you cannot reach behind your back or lift the arm. Pain can disturb sleep.",
     "It may last many months. Physiotherapy and, if needed, a specialist injection or procedure, restore movement.",
     "See a doctor for a stiff painful shoulder lasting weeks, especially if you have diabetes."),
    ("vitamin_d_deficiency", "Vitamin D Deficiency", "NIH ODS - Vitamin D", "https://ods.od.nih.gov/factsheets/VitaminD-Consumer/", "Vitamin D Deficiency", "consult_doctor",
     "Low vitamin D can cause tiredness, bone ache, and muscle weakness. Many people have no clear symptoms. A blood test measures it.",
     "Safe sun, food, and a clinician-advised supplement correct it. Do not take very high doses on your own.",
     "See a doctor if you have bone pain or are at risk (little sun, darker skin in winter, gut disease)."),
    ("vitamin_b12_deficiency", "Vitamin B12 Deficiency", "NIH ODS - Vitamin B12", "https://ods.od.nih.gov/factsheets/VitaminB12-Consumer/", "Vitamin B12 Deficiency", "consult_doctor",
     "Low B12 can cause tiredness, a sore tongue, pins and needles, and memory fog. It is more common with vegan diets or after stomach surgery.",
     "A blood test confirms it. Tablets or injections prescribed by a clinician rebuild stores.",
     "See a doctor for lasting tingling and tiredness. Do not self-inject without advice."),
    ("parkinsons", "Parkinson's Disease", "NINDS - Parkinson's Disease", "https://www.ninds.nih.gov/health-information/disorders/parkinsons-disease", "Parkinson's Disease", "consult_doctor",
     "Parkinson's is a movement condition. A resting tremor, slowness, stiff muscles, and smaller handwriting can appear gradually.",
     "A neurologist diagnoses it and offers medicines that replace dopamine signalling. Exercise is part of care.",
     "See a doctor for a new tremor or shuffling walk. Sudden chest pain or a fall with a head injury needs urgent care."),
    ("alzheimers", "Alzheimer's Disease", "NIA - Alzheimer's Disease", "https://www.nia.nih.gov/health/alzheimers-and-dementia/alzheimers-disease-fact-sheet", "Alzheimer's Disease", "consult_doctor",
     "Alzheimer's is the most common dementia. Short-term memory, finding words, and managing daily tasks slowly decline.",
     "A clinician rules out treatable causes and can discuss medicines and support. It is not normal forgetfulness of names only.",
     "See a doctor for memory loss that affects work or safety. Sudden confusion over hours is delirium and needs urgent review."),
    ("multiple_sclerosis", "Multiple Sclerosis", "NINDS - Multiple Sclerosis", "https://www.ninds.nih.gov/health-information/disorders/multiple-sclerosis", "Multiple Sclerosis", "consult_doctor",
     "MS can cause episodes of numbness, vision blur in one eye, weakness, or unsteadiness that last days. Symptoms may ease then return.",
     "A neurologist uses MRI and clinical signs. Disease-modifying treatment started early can reduce relapses.",
     "See a doctor for a first episode of one-sided vision loss or unexplained weakness. Seek emergency care for sudden inability to walk."),
    ("ocd", "Obsessive-Compulsive Disorder", "NIMH - OCD", "https://www.nimh.nih.gov/health/topics/obsessive-compulsive-disorder-ocd", "OCD", "consult_doctor",
     "OCD involves unwanted thoughts and repeated rituals (checking, washing, repeating) that take a lot of time and cause distress.",
     "Talking therapy (ERP) and, when needed, prescribed medicine help. It is not just liking things tidy.",
     "See a mental health professional if rituals control your day. Seek emergency or crisis help for thoughts of self-harm."),
    ("bipolar_disorder", "Bipolar Disorder", "NIMH - Bipolar Disorder", "https://www.nimh.nih.gov/health/topics/bipolar-disorder", "Bipolar Disorder", "consult_doctor",
     "Bipolar disorder includes episodes of very high mood or energy (mania) and episodes of depression. Sleep may drop sharply in mania.",
     "A psychiatrist diagnoses it. Mood-stabilising medicine and regular sleep protect against swings. Alcohol makes swings worse.",
     "See a clinician for extreme mood cycles. Seek emergency care if there is no sleep for days with risky behaviour, or thoughts of suicide."),
    ("ptsd", "Post-Traumatic Stress Disorder", "NIMH - PTSD", "https://www.nimh.nih.gov/health/topics/post-traumatic-stress-disorder-ptsd", "PTSD", "consult_doctor",
     "PTSD can follow a terrifying event. People get flashbacks, nightmares, jumpiness, and avoid reminders. It lasts more than a month.",
     "Trauma-focused therapy and, if needed, medicine help. Support from trusted people matters.",
     "See a professional if trauma memories disrupt life. Use emergency or crisis services if you feel unsafe now."),
    ("postpartum_depression", "Postpartum Depression", "OASH - Postpartum Depression", "https://womenshealth.gov/mental-health/mental-health-conditions/postpartum-depression", "Postpartum Depression", "consult_doctor",
     "Postpartum depression is more than a few days of baby blues. Low mood, guilt, poor sleep even when the baby sleeps, and loss of joy last weeks.",
     "It is treatable with support, therapy, and sometimes medicine that a clinician chooses for breastfeeding if needed.",
     "Tell a doctor or midwife early. Seek emergency help for thoughts of harming yourself or the baby."),
    ("atrial_fibrillation", "Atrial Fibrillation", "CDC - Atrial Fibrillation", "https://www.cdc.gov/heart-disease/about/atrial-fibrillation.html", "Atrial Fibrillation", "consult_doctor",
     "Atrial fibrillation is an irregular, often fast heartbeat. People may feel palpitations, breathlessness, or tiredness. Some feel nothing.",
     "A clinician confirms it with an ECG. Treatment may include rate control and blood thinners to lower stroke risk.",
     "See a doctor for a new irregular pulse. Seek emergency care for chest pain, fainting, or one-sided weakness."),
    ("heart_failure", "Heart Failure", "CDC - Heart Failure", "https://www.cdc.gov/heart-disease/about/heart-failure.html", "Heart Failure", "consult_doctor",
     "Heart failure means the heart cannot pump well enough. Ankles swell, breathlessness comes on walking or lying flat, and weight can rise quickly.",
     "A cardiologist uses scans and blood tests. Tablets, salt reduction, and daily weight checks are common parts of care.",
     "See a doctor for new swelling and breathlessness. Seek emergency care if you wake gasping or cannot speak in sentences."),
    ("varicose_veins", "Varicose Veins", "NHLBI - Varicose Veins", "https://www.nhlbi.nih.gov/health/varicose-veins", "Varicose Veins", "consult_doctor",
     "Varicose veins are twisted, raised leg veins. They can ache, itch, or swell by evening. Standing a long time makes them worse.",
     "Walking, raising the legs, and compression stockings if fitted, help. Procedures can treat larger veins.",
     "See a doctor for skin darkening or an ulcer near the ankle. Seek urgent care for a suddenly swollen painful calf."),
    ("peripheral_artery_disease", "Peripheral Artery Disease", "CDC - PAD", "https://www.cdc.gov/heart-disease/about/peripheral-arterial-disease.html", "Peripheral Artery Disease", "consult_doctor",
     "PAD is narrowing of leg arteries. Walking brings calf pain that eases with rest (claudication). Feet may feel cold.",
     "Stopping smoking, walking programmes, and medicines reduce heart and limb risk. A clinician checks pulses and sometimes a Doppler test.",
     "See a doctor for walking pain in the calves. Seek emergency care for a suddenly pale, cold, painful foot."),
    ("croup", "Croup", "CDC - Croup", "https://www.cdc.gov/parainfluenza/about/index.html", "Croup", "consult_doctor",
     "Croup is a viral swelling of the voice box in young children. A barking cough and hoarse voice are typical, worse at night.",
     "Sit the child upright, keep them calm, and use cool night air or steam if it helps them settle. A clinician may give steroid medicine.",
     "Seek emergency care if the child struggles to breathe, is drooling, or the breastbone sucks in with each breath."),
    ("lactose_intolerance", "Lactose Intolerance", "NIDDK - Lactose Intolerance", "https://www.niddk.nih.gov/health-information/digestive-diseases/lactose-intolerance", "Lactose Intolerance", "consult_doctor",
     "Lactose intolerance means the gut cannot digest milk sugar well. Bloating, gas, and loose stools follow milk, ice cream, or soft cheese.",
     "Lactose-free milk, smaller servings, or lactase drops help many people. Hard cheese and yoghurt are often better tolerated.",
     "See a doctor before cutting all dairy long term, so calcium needs and other gut diseases are considered."),
    ("food_allergy", "Food Allergy", "CDC - Food Allergies", "https://www.cdc.gov/food-allergies/about/index.html", "Food Allergy", "consult_doctor",
     "A food allergy is an immune reaction, often to nuts, milk, egg, or shellfish. Hives, swelling, vomiting, or wheeze can start soon after eating.",
     "An allergy clinic confirms it. The food must be avoided. Some people need an epinephrine injector prescribed for emergencies.",
     "See a doctor after a suspected reaction. Call emergency services for trouble breathing or feeling faint after a food."),
    ("prostatitis", "Prostatitis", "NIDDK - Prostatitis", "https://www.niddk.nih.gov/health-information/urologic-diseases/prostate-problems/prostatitis-infection-inflammation", "Prostatitis", "consult_doctor",
     "Prostatitis is inflammation of the prostate. Pelvic pain, burning urine, and a frequent need to go can occur. Fever suggests infection.",
     "A clinician may test urine and prescribe antibiotics if bacteria are likely. Chronic pelvic pain needs a longer plan.",
     "See a doctor for pelvic pain with urinary symptoms. Seek emergency care if you cannot pass urine or have high fever."),
    ("overactive_bladder", "Overactive Bladder", "NIDDK - Overactive Bladder", "https://www.niddk.nih.gov/health-information/urologic-diseases/bladder-control-problems", "Overactive Bladder", "consult_doctor",
     "Overactive bladder is a sudden strong urge to pass urine, often with frequent day and night trips. Leakage can happen if a toilet is not near.",
     "Bladder training, timed drinks, and pelvic-floor exercises help. A clinician may add medicine after checking for infection.",
     "See a doctor for new urgency, blood in urine, or pain, which need other causes ruled out."),
    ("restless_leg_syndrome", "Restless Legs Syndrome", "NINDS - Restless Legs Syndrome", "https://www.ninds.nih.gov/health-information/disorders/restless-legs-syndrome", "Restless Legs Syndrome", "consult_doctor",
     "RLS is an urge to move the legs, worse at rest and in the evening, with crawling or aching feelings that ease when you walk.",
     "Regular sleep, less caffeine, and treating low iron if a clinician finds it, help many people.",
     "See a doctor if nights are ruined. Do not start dopamine tablets on your own."),
    ("obesity", "Obesity", "CDC - About Obesity", "https://www.cdc.gov/obesity/php/about/index.html", "Obesity", "consult_doctor",
     "Obesity is extra body fat that raises risk of diabetes, heart disease, and joint pain. It is a health condition, not a moral failing.",
     "A clinician can plan food, activity, and, if suitable, medicine or surgery. Small lasting changes beat crash diets.",
     "See a doctor for a weight plan if BMI is high or weight-related illness is present."),
    ("heat_exhaustion", "Heat Exhaustion", "CDC - Heat Exhaustion", "https://www.cdc.gov/niosh/heat-stress/about/heat-exhaustion.html", "Heat Exhaustion", "consult_doctor",
     "Heat exhaustion causes heavy sweating, weakness, nausea, headache, and a fast pulse after heat or hard work. The person is usually still aware.",
     "Move to shade, loosen clothes, sip water, and cool the skin. Rest until recovered.",
     "Seek emergency care if confusion, fainting, or very hot dry skin develops, which can be heat stroke."),
    ("rotator_cuff", "Rotator Cuff Problem", "NIAMS - Rotator Cuff Tears", "https://www.niams.nih.gov/health-topics/rotator-cuff-tears", "Rotator Cuff Injury", "consult_doctor",
     "The rotator cuff is a group of shoulder tendons. Pain when lifting the arm, night pain when lying on that side, and weakness are typical.",
     "Physiotherapy is first for many tears and tendinopathy. A scan is used if weakness is sudden after an injury.",
     "See a doctor after a fall if you cannot lift the arm. Seek urgent care for a cold numb arm."),
    ("retinal_detachment", "Retinal Detachment", "NEI - Retinal Detachment", "https://www.nei.nih.gov/learn-about-eye-health/eye-conditions-and-diseases/retinal-detachment", "Retinal Detachment", "emergency",
     "A detaching retina causes a sudden shower of floaters, flashes, or a dark curtain across part of the vision, usually in one eye.",
     "This is an eye emergency. Surgery or a laser procedure may save sight if done quickly. Do not wait to see if it 'clears'.",
     "Go to an emergency eye service the same day. Do not drive yourself if vision is badly reduced."),
    ("preeclampsia", "Preeclampsia", "CDC - High Blood Pressure During Pregnancy", "https://www.cdc.gov/high-blood-pressure/about/preeclampsia.html", "Preeclampsia", "emergency",
     "Preeclampsia is high blood pressure in later pregnancy with signs that organs are stressed. Headache, vision spots, swelling, and upper belly pain can appear.",
     "It can become life-threatening for parent and baby. Hospital assessment, blood tests, and blood pressure treatment are needed.",
     "Seek emergency maternity care for headache, flashing lights, or sudden swelling in pregnancy."),
    ("hypothermia", "Hypothermia", "CDC - Hypothermia", "https://www.cdc.gov/winter-weather/prevention/prevent-hypothermia-and-frostbite.html", "Hypothermia", "emergency",
     "Hypothermia is a dangerously low body temperature after cold exposure. Shivering, slurred speech, clumsiness, and sleepiness are warning signs.",
     "Call emergency services. Move the person to shelter, remove wet clothes, and warm the trunk with blankets. Do not give alcohol.",
     "This is an emergency even if the person wants to 'rest'. Infants and older adults are at higher risk."),
    ("snake_bite", "Snake Bite", "CDC - Venomous Snakes", "https://www.cdc.gov/niosh/outdoor-workers/about/venomous-snakes.html", "Snake Bite", "emergency",
     "A venomous snake bite can cause severe pain, swelling, and later bleeding or paralysis. Any bite from an unknown snake should be treated as serious.",
     "Call emergency services. Keep the person still, immobilise the limb, and remove rings. Do not cut, suck, or apply a tight tourniquet.",
     "Go to hospital even if you feel well at first, because venom effects can be delayed."),
    ("choking", "Choking", "CDC - Choking", "https://www.cdc.gov/child-injury/about/index.html", "Choking", "emergency",
     "Choking means the airway is blocked. The person cannot speak, cough, or breathe well, and may clutch the throat.",
     "Call emergency services. Give back blows and abdominal thrusts if you are trained. Do not do blind finger sweeps.",
     "Even after the object comes out, hospital review is wise if breathing was difficult."),
    ("alcohol_poisoning", "Alcohol Poisoning", "CDC - Alcohol Poisoning", "https://www.cdc.gov/alcohol/about/alcohol-overdose.html", "Alcohol Poisoning", "emergency",
     "Alcohol poisoning is a medical emergency after a large amount of alcohol. Vomiting, slow breathing, cold skin, and unresponsiveness occur.",
     "Call emergency services. Roll the person on their side. Do not leave them to 'sleep it off' or give more alcohol or coffee.",
     "This can be fatal. Stay until help arrives."),
    ("aortic_dissection", "Aortic Dissection", "AHA - Aortic Dissection", "https://www.heart.org/en/health-topics/aortic-aneurysm", "Aortic Dissection", "emergency",
     "Aortic dissection is a tear in the main body artery. People feel sudden tearing chest or back pain, often at peak intensity from the first second.",
     "This is a surgical emergency. Do not wait to see if antacids help. Blood pressure control in hospital is urgent.",
     "Call emergency services for sudden tearing chest or back pain, especially with a difference in arm pulses."),
    ("bowel_obstruction", "Bowel Obstruction", "NIDDK - Intestinal Obstruction", "https://www.niddk.nih.gov/health-information/digestive-diseases/intestinal-pseudo-obstruction", "Bowel Obstruction", "emergency",
     "A blocked bowel causes cramping pain, bloating, vomiting, and no wind or stool. Prior surgery raises risk because of adhesions.",
     "Hospital scans and drips are needed. Some blockages need surgery. Do not eat or drink while waiting for care.",
     "Go to emergency care for vomiting and a silent, swollen abdomen."),
    ("urinary_retention", "Acute Urinary Retention", "NIDDK - Urinary Retention", "https://www.niddk.nih.gov/health-information/urologic-diseases/urinary-retention", "Urinary Retention", "emergency",
     "Acute retention means you suddenly cannot pass urine and the bladder is painfully full. It is more common in older men with prostate enlargement.",
     "A catheter in hospital relieves it. The cause is then treated. Waiting at home can damage the kidneys.",
     "Go to emergency care if you cannot pass urine and the lower belly is painful and swollen."),
    ("septic_arthritis", "Septic Arthritis", "CDC - Arthritis", "https://www.cdc.gov/arthritis/basics/index.html", "Septic Arthritis", "emergency",
     "Septic arthritis is infection inside a joint. One joint becomes suddenly hot, swollen, and so painful you will not move it. Fever is common.",
     "This needs emergency hospital drainage and antibiotics. Delay can destroy the joint.",
     "Go to emergency care for a single hot joint you cannot move, especially after a joint injection or if you have a weak immune system."),
    ("cauda_equina", "Cauda Equina Syndrome", "NINDS - Cauda Equina Syndrome", "https://www.ninds.nih.gov/health-information/disorders/cauda-equina-syndrome", "Cauda Equina Syndrome", "emergency",
     "Cauda equina syndrome is pressure on the nerve bundle at the base of the spine. Warning signs are saddle numbness, loss of bladder or bowel control, and weak legs.",
     "Emergency MRI and surgery can save nerve function. Do not wait for a routine back-pain clinic.",
     "Go to emergency care the same hour for back pain with new saddle numbness or incontinence."),
    ("necrotizing_fasciitis", "Necrotizing Fasciitis", "CDC - Necrotizing Fasciitis", "https://www.cdc.gov/groupastrep/diseases-public/necrotizing-fasciitis.html", "Necrotizing Fasciitis", "emergency",
     "This is a rapidly spreading deep infection. Pain is out of proportion to the skin change. The area may look dusky, and the person becomes very unwell.",
     "Emergency surgery and antibiotics are life-saving. It is not ordinary cellulitis.",
     "Call emergency services for severe pain after a small wound with rapid darkening of the skin and fever."),
    ("rabies_exposure", "Possible Rabies Exposure", "CDC - Rabies", "https://www.cdc.gov/rabies/about/index.html", "Rabies Exposure", "emergency",
     "Rabies is almost always fatal once symptoms start. Any bite or scratch from a bat or a mammal that might have rabies is an emergency even if the wound is small.",
     "Wash the wound with soap and water for 15 minutes and go to emergency care for vaccines and, if needed, immunoglobulin. Do not wait for symptoms.",
     "Seek care the same day after a suspect bite, including a bat found in a room with a sleeping person."),
    ("stevens_johnson", "Stevens-Johnson Syndrome", "MedlinePlus - Stevens-Johnson", "https://medlineplus.gov/ency/article/000851.htm", "Stevens-Johnson Syndrome", "emergency",
     "SJS is a rare severe reaction, often to a new medicine. The skin blisters, the mouth and eyes become raw, and fever starts.",
     "Stop the suspected drug if a clinician agrees it is safe to stop, and go to hospital. This can progress to a burn-like emergency.",
     "Seek emergency care for blistering rash with sore mouth or eyes after starting a new medicine."),
    ("sickle_cell_crisis", "Sickle Cell Pain Crisis", "CDC - Sickle Cell Disease", "https://www.cdc.gov/sickle-cell/about/index.html", "Sickle Cell Crisis", "emergency",
     "A sickle cell crisis is sudden severe pain in bones, chest, or abdomen when red cells sickle and block flow. Fever or chest pain can mean danger.",
     "People with known sickle cell disease need urgent fluids, oxygen, and strong pain care in hospital. Home rest is not enough for a severe crisis.",
     "Go to emergency care for a severe crisis, chest pain, or fever if you have sickle cell disease."),
]

MORE_DOCUMENTS = [
    (row[0], row[1], row[2], row[3], row[4], row[5], f"{row[6]}\n\n{row[7]}\n\n{row[8]}")
    for row in _RAW
]
